def _copy(keys):
    out = []
    for k in keys:
        nk = {kk: vv for kk, vv in k.items() if kk not in ("R", "L")}
        nk["R"] = dict(k["R"])
        if "L" in k and isinstance(k["L"], dict):
            nk["L"] = dict(k["L"])
        elif "L" in k:
            nk["L"] = k["L"]
        out.append(nk)
    return out


def _extend(keys, dy, extra):
    keys = _copy(keys)
    last = keys[-1]
    r = dict(last["R"])
    r["dy"] = r.get("dy", 0) + dy
    keys.append({**{kk: vv for kk, vv in last.items() if kk != "R"}, "t": round(last["t"] + extra, 2), "R": r})
    return keys


def hi_keys(ak, lat):
    if ak in CONJUNCT:
        return CONJUNCT[ak]
    keys = LETTERS[lat]
    if ak in RETRO:
        keys = _copy(keys)
        for k in keys:
            k["R"]["roll"] = max(-1, min(1, k["R"].get("roll", 0) - 0.4))
    if ak in LONG:
        return _extend(keys, 6, 0.2)
    if ak in ASP:
        return _extend(keys, -5, 0.15)
    if ak == "अं":
        return _extend(keys, 4, 0.15)
    return keys

