def mirrored(frames, step=0.35, face=None):
    """Both hands doing the same thing on their own side: dx is outward, so one key serves both."""
    keys = [{"t": round(i * step, 2), "R": f, "L": f} for i, f in enumerate(frames)]
    if face:
        keys[0]["face"] = face
    return keys


